public class MainActivity extends Activity {
    static final String API="https://okizneyesdwiundvadpe.supabase.co/functions/v1/api";
    LinearLayout root,content,drawer; FrameLayout shell; TextView title; String session="",role=""; final ArrayDeque<String> history=new ArrayDeque<>();
    int navy=Color.rgb(12,28,45),teal=Color.rgb(13,137,137),bg=Color.rgb(244,247,250),white=Color.WHITE,text=Color.rgb(32,45,58),muted=Color.rgb(105,119,132);
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable box(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
    TextView tv(String s,float z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setPadding(dp(16),dp(8),dp(16),dp(8));return t;}
    Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setTextColor(white);b.setAllCaps(false);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setBackground(box(teal,18));return b;}
    EditText input(String h){EditText e=new EditText(this);e.setHint(h);e.setTextSize(15);e.setTextColor(text);e.setHintTextColor(Color.rgb(150,160,170));e.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);e.setPadding(dp(16),0,dp(16),0);e.setSingleLine(true);e.setBackground(box(white,16));return e;}
    Space gap(int h){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(1,dp(h)));return s;}
    @Override public void onCreate(Bundle b){super.onCreate(b);showLogin();}
    void frame(String page,boolean inner){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(10),dp(8),dp(10),dp(8));bar.setBackgroundColor(navy);TextView nav=tv(inner?"‹":"☰",30,white);nav.setGravity(Gravity.CENTER);bar.addView(nav,new LinearLayout.LayoutParams(dp(52),dp(48)));title=tv(page,18,white);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);bar.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(bar,new LinearLayout.LayoutParams(-1,dp(64)));shell=new FrameLayout(this);root.addView(shell,new LinearLayout.LayoutParams(-1,0,1));ScrollView sv=new ScrollView(this);sv.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(18),dp(18),dp(18),dp(28));content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);sv.addView(content);shell.addView(sv,new FrameLayout.LayoutParams(-1,-1));drawer=new LinearLayout(this);drawer.setOrientation(LinearLayout.VERTICAL);drawer.setPadding(dp(18),dp(24),dp(18),dp(18));drawer.setBackgroundColor(white);drawer.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);shell.addView(drawer,new FrameLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.84),-1,Gravity.RIGHT));drawer.setVisibility(View.GONE);nav.setOnClickListener(v->{if(inner)backPage();else toggleDrawer();});}
    void toggleDrawer(){if(drawer!=null)drawer.setVisibility(drawer.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);}
    void open(String id){if(history.isEmpty()||!history.peekLast().equals(id))history.addLast(id);show(id);}
    void show(String id){if(id.equals("manager"))managerHome();else if(id.equals("units"))units();else if(id.equals("charges"))charges();else if(id.equals("repairs"))repairs();else if(id.equals("payments"))payments();else if(id.equals("plans"))plans();else if(id.equals("resident"))residentHome();else if(id.equals("resident_pay"))residentPay();else if(id.equals("admin"))adminHome();else if(id.equals("admin_buildings"))adminBuildings();else if(id.equals("admin_plans"))adminPlans();else if(id.equals("admin_settings"))adminSettings();else showLogin();}
    void backPage(){if(drawer!=null&&drawer.getVisibility()==View.VISIBLE){drawer.setVisibility(View.GONE);return;}if(history.size()>1){history.removeLast();show(history.peekLast());}else{session="";role="";history.clear();showLogin();}}
    @Override public void onBackPressed(){if(drawer!=null&&drawer.getVisibility()==View.VISIBLE){drawer.setVisibility(View.GONE);return;}if(history.size()>1){backPage();return;}if(!role.isEmpty()){session="";role="";history.clear();showLogin();return;}super.onBackPressed();}
    void header(String a,String b){LinearLayout h=new LinearLayout(this);h.setOrientation(LinearLayout.VERTICAL);h.setPadding(dp(18),dp(16),dp(18),dp(16));h.setBackground(box(navy,22));TextView x=tv(a,20,white);x.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h.addView(x);h.addView(tv(b,13,Color.rgb(190,210,220)));content.addView(h,new LinearLayout.LayoutParams(-1,dp(108)));content.addView(gap(14));}
    void stat(String n,String v,String ic){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(12),dp(16),dp(12));c.setBackground(box(white,20));c.addView(tv(ic,21,teal));c.addView(tv(n,12,muted));TextView z=tv(v,18,navy);z.setTypeface(Typeface.DEFAULT,Typeface.BOLD);c.addView(z);content.addView(c,new LinearLayout.LayoutParams(-1,dp(100)));content.addView(gap(10));}
    void card(String h,String v){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(10),dp(16),dp(10));c.setBackground(box(white,18));TextView a=tv(h,13,muted);a.setTypeface(Typeface.DEFAULT,Typeface.BOLD);c.addView(a);TextView b=tv(v,17,teal);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);c.addView(b);content.addView(c,new LinearLayout.LayoutParams(-1,dp(80)));content.addView(gap(9));}
    void section(String s){TextView t=tv(s,16,navy);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);content.addView(t,new LinearLayout.LayoutParams(-1,dp(42)));}
    void menuItem(String s,String ic,String page){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(10),0,dp(10),0);r.setBackground(box(Color.rgb(245,248,250),16));r.addView(tv(ic,21,teal),new LinearLayout.LayoutParams(dp(44),dp(50)));TextView n=tv(s,15,navy);n.setTypeface(Typeface.DEFAULT,Typeface.BOLD);r.addView(n,new LinearLayout.LayoutParams(0,dp(50),1));r.setOnClickListener(v->{drawer.setVisibility(View.GONE);open(page);});drawer.addView(r,new LinearLayout.LayoutParams(-1,dp(50)));drawer.addView(gap(8));}
    void drawerHead(String roleName){drawer.removeAllViews();LinearLayout h=new LinearLayout(this);h.setOrientation(LinearLayout.VERTICAL);h.setPadding(dp(16),dp(14),dp(16),dp(14));h.setBackground(box(navy,20));h.addView(tv("ساختمان‌یار",20,white));h.addView(tv(roleName,12,Color.rgb(190,210,220)));drawer.addView(h,new LinearLayout.LayoutParams(-1,dp(90)));drawer.addView(gap(14));}
    void managerDrawer(){drawerHead("مدیر ساختمان");menuItem("داشبورد","⌂","manager");menuItem("واحدها و ساکنان","▣","units");menuItem("شارژ و هزینه‌ها","₮","charges");menuItem("تعمیرات","⚒","repairs");menuItem("پرداخت‌ها","✓","payments");menuItem("اشتراک سامانه","★","plans");menuItem("خروج","↪","login");}
    void residentDrawer(){drawerHead("ساکن");menuItem("داشبورد من","⌂","resident");menuItem("پرداخت بدهی","₮","resident_pay");menuItem("خروج","↪","login");}
    void adminDrawer(){drawerHead("مدیرکل سامانه");menuItem("داشبورد سامانه","⌂","admin");menuItem("ساختمان‌ها","▣","admin_buildings");menuItem("اشتراک‌ها","★","admin_plans");menuItem("تنظیمات سامانه","⚙","admin_settings");menuItem("خروج","↪","login");}
    void showLogin(){role="";session="";history.clear();frame("ورود به سامانه",false);content.setGravity(Gravity.CENTER_HORIZONTAL);content.addView(gap(24));TextView logo=tv("ساختمان‌یار",30,teal);logo.setGravity(Gravity.CENTER);logo.setTypeface(Typeface.DEFAULT,Typeface.BOLD);content.addView(logo,new LinearLayout.LayoutParams(-1,dp(60)));TextView sub=tv("مدیریت هوشمند ساختمان",15,muted);sub.setGravity(Gravity.CENTER);content.addView(sub);content.addView(gap(20));EditText u=input("نام کاربری"),p=input("رمز عبور");p.setInputType(129);content.addView(u,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(p,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(15));Button m=btn("ورود مدیر ساختمان"),r=btn("ورود ساکن"),a=btn("ورود مدیرکل سامانه"),reg=btn("ثبت مدیر اولیه");content.addView(m,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(gap(8));content.addView(r,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(gap(8));content.addView(a,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(gap(8));content.addView(reg,new LinearLayout.LayoutParams(-1,dp(52)));m.setOnClickListener(v->login(u.getText().toString().trim(),p.getText().toString(),"manager"));r.setOnClickListener(v->login(u.getText().toString().trim(),p.getText().toString(),"resident"));a.setOnClickListener(v->login(u.getText().toString().trim(),p.getText().toString(),"admin"));reg.setOnClickListener(v->register());}
    void login(String u,String p,String r){if(u.isEmpty()||p.isEmpty()){toast("نام کاربری و رمز عبور را وارد کنید");return;}new Thread(()->{try{JSONObject b=new JSONObject().put("action",r.equals("admin")?"admin_login":r.equals("resident")?"login_resident":"login_manager").put("username",u).put("password",p);JSONObject j=new JSONObject(post(b,null));if(j.has("error"))throw new Exception(j.getString("error"));session=j.getString("session");role=r;history.clear();history.addLast(r.equals("admin")?"admin":r.equals("resident")?"resident":"manager");runOnUiThread(()->{if(r.equals("admin"))adminHome();else if(r.equals("resident"))residentHome();else managerHome();});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}).start();}
    void register(){frame("ثبت مدیر اولیه",true);EditText n=input("نام ساختمان"),ad=input("آدرس ساختمان"),u=input("نام کاربری مدیر"),p=input("رمز عبور");p.setInputType(129);content.addView(n,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(ad,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(u,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(p,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(15));Button b=btn("ثبت ساختمان");content.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->new Thread(()->{try{JSONObject j=new JSONObject().put("action","register_manager").put("building_name",n.getText().toString()).put("address",ad.getText().toString()).put("username",u.getText().toString()).put("password",p.getText().toString());JSONObject z=new JSONObject(post(j,null));if(z.has("error"))throw new Exception(z.getString("error"));session=z.getString("session");role="manager";history.clear();history.addLast("manager");runOnUiThread(this::managerHome);}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}).start());}
    void managerHome(){frame("داشبورد مدیر ساختمان",false);managerDrawer();header("داشبورد مدیریت ساختمان","نمای کلی وضعیت ساختمان");stat("واحدها","مشاهده و مدیریت","▣");stat("امور مالی","شارژ و هزینه‌ها","₮");stat("تعمیرات","ثبت و پیگیری","⚒");stat("پرداخت‌ها","بررسی و تأیید","✓");}
    void units(){frame("واحدها و ساکنان",true);managerDrawer();section("مدیریت واحدها");Button add=btn("＋ افزودن واحد");content.addView(add,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(gap(10));add.setOnClickListener(v->addUnit());call("dashboard",j->{JSONArray a=j.optJSONArray("units");if(a!=null)for(int i=0;i<a.length();i++){org.json.JSONObject x=a.getJSONObject(i);card("واحد "+x.optString("unit_no"),"تعداد ساکن: "+x.optInt("resident_count"));}});}
    void addUnit(){frame("افزودن واحد",true);EditText n=input("شماره واحد"),r=input("تعداد ساکن"),o=input("نام مالک / ساکن");content.addView(n,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(r,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(o,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(15));Button b=btn("ذخیره واحد");content.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->callObj(new JSONObject().put("action","add_unit").put("unit_no",n.getText().toString()).put("residents_count",r.getText().toString()).put("resident_name",o.getText().toString()),j->{toast("واحد ثبت شد");open("units");}));}
    void charges(){frame("شارژ و هزینه‌ها",true);managerDrawer();Button b=btn("＋ ثبت هزینه جدید");content.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(gap(10));b.setOnClickListener(v->addCharge());call("dashboard",j->{JSONArray a=j.optJSONArray("charges");if(a!=null)for(int i=0;i<a.length();i++){org.json.JSONObject x=a.getJSONObject(i);card(x.optString("title"),money(x.optDouble("amount_rial")));}});}
    void addCharge(){frame("ثبت هزینه",true);EditText t=input("عنوان هزینه"),a=input("مبلغ به تومان");content.addView(t,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(a,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(15));Button b=btn("ثبت هزینه");content.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->{try{long amount=Long.parseLong(a.getText().toString().trim())*10;callObj(new JSONObject().put("action","add_charge").put("title",t.getText().toString()).put("amount_rial",amount),j->{toast("هزینه ثبت شد");open("charges");});}catch(Exception e){toast("مبلغ نامعتبر است");}});}
    void repairs(){frame("تعمیرات",true);managerDrawer();Button b=btn("＋ ثبت تعمیرات");content.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(gap(10));b.setOnClickListener(v->addRepair());call("dashboard",j->{JSONArray a=j.optJSONArray("repairs");if(a!=null)for(int i=0;i<a.length();i++){org.json.JSONObject x=a.getJSONObject(i);card(x.optString("title"),money(x.optDouble("amount")));}});}
    void addRepair(){frame("ثبت تعمیرات",true);EditText t=input("عنوان تعمیر"),a=input("مبلغ به تومان"),d=input("توضیحات");content.addView(t,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(a,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(d,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(15));Button b=btn("ثبت تعمیر");content.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->{try{long amount=Long.parseLong(a.getText().toString().trim())*10;callObj(new JSONObject().put("action","add_repair").put("title",t.getText().toString()).put("amount_rial",amount).put("description",d.getText().toString()),j->{toast("تعمیر ثبت شد");open("repairs");});}catch(Exception e){toast("مبلغ نامعتبر است");}});}
    void payments(){frame("پرداخت‌ها",true);managerDrawer();call("dashboard",j->{JSONArray a=j.optJSONArray("payments");if(a!=null)for(int i=0;i<a.length();i++){org.json.JSONObject x=a.getJSONObject(i);card("پرداخت واحد "+x.optString("unit_id"),money(x.optDouble("amount"))+"  •  "+x.optString("status"));}});}
    void plans(){frame("اشتراک سامانه",true);managerDrawer();call("list_plans",j->{JSONArray a=j.optJSONArray("data");if(a==null)a=j.optJSONArray("plans");if(a!=null)for(int i=0;i<a.length();i++){org.json.JSONObject x=a.getJSONObject(i);card(x.optString("name"),money(x.optDouble("price_rial"))+" / "+x.optInt("duration_days")+" روز");}});}
    void residentHome(){frame("داشبورد ساکن",false);residentDrawer();header("پنل ساکن","اطلاعات مالی واحد شما");call("dashboard",j->{org.json.JSONObject u=j.optJSONObject("unit");stat("واحد من",u==null?"-":u.optString("unit_no"),"⌂");JSONArray p=j.optJSONArray("payments");stat("پرداخت‌های ثبت‌شده",String.valueOf(p==null?0:p.length()),"✓");});}
    void residentPay(){frame("پرداخت بدهی",true);residentDrawer();EditText a=input("مبلغ پرداخت به تومان"),n=input("توضیحات");content.addView(a,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(9));content.addView(n,new LinearLayout.LayoutParams(-1,dp(56)));content.addView(gap(15));Button b=btn("ثبت پرداخت");content.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->{try{long amount=Long.parseLong(a.getText().toString().trim())*10;callObj(new JSONObject().put("action","add_payment").put("amount_rial",amount).put("note",n.getText().toString()),j->toast("پرداخت برای تأیید مدیر ثبت شد"));}catch(Exception e){toast("مبلغ نامعتبر است");}});}
    void adminHome(){frame("داشبورد مدیرکل سامانه",false);adminDrawer();header("مدیرکل سامانه","کنترل ساختمان‌ها و اشتراک‌ها");call("admin_dashboard",j->{JSONArray b=j.optJSONArray("buildings"),p=j.optJSONArray("plans"),r=j.optJSONArray("requests");stat("ساختمان‌ها",String.valueOf(b==null?0:b.length()),"▣");stat("طرح‌های اشتراک",String.valueOf(p==null?0:p.length()),"★");stat("درخواست‌های اشتراک",String.valueOf(r==null?0:r.length()),"◷");});}
    void adminBuildings(){frame("مدیریت ساختمان‌ها",true);adminDrawer();call("admin_dashboard",j->{JSONArray a=j.optJSONArray("buildings");if(a!=null)for(int i=0;i<a.length();i++){org.json.JSONObject x=a.getJSONObject(i);card(x.optString("name"),x.optString("subscription_status"));}});}
    void adminPlans(){frame("مدیریت اشتراک‌ها",true);adminDrawer();call("admin_dashboard",j->{JSONArray a=j.optJSONArray("plans");if(a!=null)for(int i=0;i<a.length();i++){org.json.JSONObject x=a.getJSONObject(i);card(x.optString("name"),money(x.optDouble("price_rial"))+" / "+x.optInt("duration_days")+" روز");}});}
    void adminSettings(){frame("تنظیمات سامانه",true);adminDrawer();call("admin_dashboard",j->{org.json.JSONObject x=j.optJSONObject("settings");if(x!=null){card("نام برنامه",x.optString("app_name"));card("دوره آزمایشی",x.optString("free_trial_days")+" روز");card("تأیید ایمیل",x.optBoolean("email_verification_enabled")?"فعال":"غیرفعال");card("درگاه پرداخت",x.optBoolean("payment_gateway_enabled")?"فعال":"غیرفعال");}});}
    void call(String action,final Handler h){new Thread(()->{try{JSONObject j=new JSONObject(post(new JSONObject().put("action",action),session));if(j.has("error"))throw new Exception(j.getString("error"));runOnUiThread(()->{try{h.handle(j);}catch(Exception e){toast(e.getMessage());}});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"خطا در دریافت اطلاعات":e.getMessage()));}}).start();}
    void callObj(JSONObject b,final Handler h){new Thread(()->{try{JSONObject j=new JSONObject(post(b,session));if(j.has("error"))throw new Exception(j.getString("error"));runOnUiThread(()->{try{h.handle(j);}catch(Exception e){toast(e.getMessage());}});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"خطا در ارتباط با سامانه":e.getMessage()));}}).start();}
    String post(JSONObject b,String tok)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(API).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");if(tok!=null&&!tok.isEmpty())c.setRequestProperty("Authorization","Bearer "+tok);c.getOutputStream().write(b.toString().getBytes(StandardCharsets.UTF_8));int code=c.getResponseCode();java.io.InputStream is=code<400?c.getInputStream():c.getErrorStream();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=is.read(buf))!=-1)out.write(buf,0,n);String s=new String(out.toByteArray(),StandardCharsets.UTF_8);if(code>=400&&s.isEmpty())throw new Exception("خطای ارتباط با سرور");return s;}
    String money(double rial){return String.format(Locale.US,"%.0f تومان",rial/10.0);}
    void toast(String s){Toast.makeText(this,s==null?"خطا":s,Toast.LENGTH_LONG).show();}
    interface Handler{void handle(JSONObject j)throws Exception;}
}
